CREATE TABLE public.projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200), description text NOT NULL DEFAULT '', objective text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','active','paused','completed','archived')), priority text NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high','urgent')), category text NOT NULL DEFAULT 'general', start_date date, end_date date, owner_id uuid, source_message_id uuid REFERENCES public.messages(id), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,org_id,workspace_id));
GRANT SELECT,INSERT,UPDATE ON public.projects TO authenticated; GRANT ALL ON public.projects TO service_role; ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.campaigns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200), description text NOT NULL DEFAULT '', objective text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','active','paused','completed','archived')), priority text NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high','urgent')), category text NOT NULL DEFAULT 'marketing' CHECK(category IN ('marketing','seo','content','social','advertising','email','sales')), audience text NOT NULL DEFAULT '', budget_eur numeric NOT NULL DEFAULT 0 CHECK(budget_eur>=0), channels text[] NOT NULL DEFAULT '{}', results text NOT NULL DEFAULT '', start_date date, end_date date, owner_id uuid, source_message_id uuid REFERENCES public.messages(id), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,org_id,workspace_id));
GRANT SELECT,INSERT,UPDATE ON public.campaigns TO authenticated; GRANT ALL ON public.campaigns TO service_role; ALTER TABLE public.campaigns ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200), description text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','in_progress','review','done','cancelled')), priority text NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high','urgent')), due_date date, start_date date, project_id uuid, campaign_id uuid, parent_task_id uuid, owner_id uuid, agent_key text CHECK(agent_key IS NULL OR agent_key='growth_officer'), labels text[] NOT NULL DEFAULT '{}', recurrence text NOT NULL DEFAULT 'none' CHECK(recurrence IN ('none','weekly','monthly')), source_message_id uuid REFERENCES public.messages(id), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,org_id,workspace_id), FOREIGN KEY(project_id,org_id,workspace_id) REFERENCES public.projects(id,org_id,workspace_id), FOREIGN KEY(campaign_id,org_id,workspace_id) REFERENCES public.campaigns(id,org_id,workspace_id), FOREIGN KEY(parent_task_id,org_id,workspace_id) REFERENCES public.tasks(id,org_id,workspace_id), CHECK(parent_task_id IS DISTINCT FROM id));
GRANT SELECT,INSERT,UPDATE ON public.tasks TO authenticated; GRANT ALL ON public.tasks TO service_role; ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.execution_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),entity_type text NOT NULL CHECK(entity_type IN ('projects','tasks','campaigns')),entity_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('comment','milestone','asset','member','dependency','approval')),title text NOT NULL DEFAULT '',body text NOT NULL DEFAULT '',due_date date,completed boolean NOT NULL DEFAULT false,related_id uuid,user_id uuid,storage_path text,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.execution_notes TO authenticated; GRANT ALL ON public.execution_notes TO service_role; ALTER TABLE public.execution_notes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.activity_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),entity_type text NOT NULL,entity_id uuid NOT NULL,actor_id uuid,action text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity_events TO authenticated; GRANT ALL ON public.activity_events TO service_role; ALTER TABLE public.activity_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY execution_activity_read ON public.activity_events FOR SELECT TO authenticated USING(public.has_workspace_role(workspace_id,'viewer'));
CREATE TABLE public.execution_conversions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),source_message_id uuid NOT NULL REFERENCES public.messages(id),kind text NOT NULL CHECK(kind IN ('project','tasks','campaign')),request_key uuid NOT NULL,created_by uuid NOT NULL DEFAULT auth.uid(),result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,source_message_id,kind),UNIQUE(workspace_id,request_key));
GRANT SELECT ON public.execution_conversions TO authenticated; GRANT ALL ON public.execution_conversions TO service_role; ALTER TABLE public.execution_conversions ENABLE ROW LEVEL SECURITY;
CREATE POLICY execution_conversion_read ON public.execution_conversions FOR SELECT TO authenticated USING(created_by=auth.uid() AND public.has_workspace_role(workspace_id,'viewer'));
CREATE OR REPLACE FUNCTION public.execution_user_allowed(_workspace uuid,_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user IS NULL OR EXISTS(SELECT 1 FROM public.workspaces w JOIN public.organization_members m ON m.org_id=w.org_id JOIN public.organizations o ON o.id=w.org_id WHERE w.id=_workspace AND m.user_id=_user AND o.status='active' AND public.role_rank(m.role)>=2 AND (m.role='owner' OR EXISTS(SELECT 1 FROM public.workspace_members wm WHERE wm.workspace_id=w.id AND wm.user_id=_user AND public.role_rank(wm.role)>=2))) $$;
REVOKE ALL ON FUNCTION public.execution_user_allowed(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.execution_user_allowed(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_execution() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n jsonb:=to_jsonb(NEW); oldj jsonb; oid uuid; wid uuid; pid uuid; tid uuid; typ text; dep uuid; BEGIN
SELECT org_id INTO oid FROM public.workspaces WHERE id=NEW.workspace_id; IF oid IS DISTINCT FROM NEW.org_id THEN RAISE EXCEPTION 'Workspace organization mismatch'; END IF;
IF TG_OP='UPDATE' THEN oldj:=to_jsonb(OLD); IF NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id OR n->>'created_by' IS DISTINCT FROM oldj->>'created_by' OR n->>'source_message_id' IS DISTINCT FROM oldj->>'source_message_id' THEN RAISE EXCEPTION 'Execution identity is immutable'; END IF; END IF;
IF NOT public.execution_user_allowed(NEW.workspace_id,(n->>'owner_id')::uuid) OR NOT public.execution_user_allowed(NEW.workspace_id,(n->>'user_id')::uuid) THEN RAISE EXCEPTION 'Assignee needs workspace member access'; END IF;
IF n->>'start_date' IS NOT NULL AND coalesce(n->>'end_date',n->>'due_date') IS NOT NULL AND (n->>'start_date')::date>coalesce(n->>'end_date',n->>'due_date')::date THEN RAISE EXCEPTION 'End date precedes start date'; END IF;
IF n->>'source_message_id' IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.messages m JOIN public.conversations c ON c.id=m.conversation_id WHERE m.id=(n->>'source_message_id')::uuid AND c.org_id=NEW.org_id AND c.workspace_id=NEW.workspace_id AND c.user_id=auth.uid() AND m.role='assistant') THEN RAISE EXCEPTION 'Source recommendation unavailable'; END IF; END IF;
IF TG_TABLE_NAME='tasks' THEN
IF NEW.parent_task_id IS NOT NULL THEN IF EXISTS(WITH RECURSIVE parents AS(SELECT id,parent_task_id FROM public.tasks WHERE id=NEW.parent_task_id UNION SELECT t.id,t.parent_task_id FROM public.tasks t JOIN parents p ON t.id=p.parent_task_id) SELECT 1 FROM parents WHERE id=NEW.id) THEN RAISE EXCEPTION 'Subtask cycle'; END IF; END IF;
IF NEW.status='done' AND EXISTS(SELECT 1 FROM public.execution_notes en JOIN public.tasks t ON t.id=en.related_id WHERE en.entity_id=NEW.id AND en.kind='dependency' AND t.status NOT IN ('done','cancelled')) THEN RAISE EXCEPTION 'Complete dependencies first'; END IF;
END IF;
IF TG_TABLE_NAME='execution_notes' THEN typ:=NEW.entity_type; EXECUTE format('SELECT org_id,workspace_id FROM public.%I WHERE id=$1',typ) INTO oid,wid USING NEW.entity_id; IF oid IS DISTINCT FROM NEW.org_id OR wid IS DISTINCT FROM NEW.workspace_id THEN RAISE EXCEPTION 'Parent scope mismatch'; END IF;
IF NEW.kind='dependency' THEN IF typ<>'tasks' OR NEW.related_id IS NULL OR NEW.related_id=NEW.entity_id OR NOT EXISTS(SELECT 1 FROM public.tasks WHERE id=NEW.related_id AND workspace_id=NEW.workspace_id AND org_id=NEW.org_id) THEN RAISE EXCEPTION 'Invalid dependency'; END IF;
IF EXISTS(WITH RECURSIVE chain AS(SELECT related_id FROM public.execution_notes WHERE entity_id=NEW.related_id AND kind='dependency' UNION SELECT en.related_id FROM public.execution_notes en JOIN chain c ON en.entity_id=c.related_id WHERE en.kind='dependency') SELECT 1 FROM chain WHERE related_id=NEW.entity_id) THEN RAISE EXCEPTION 'Dependency cycle'; END IF; END IF;
IF NEW.kind='approval' AND NOT EXISTS(SELECT 1 FROM public.approvals WHERE id=NEW.related_id AND org_id=NEW.org_id AND workspace_id=NEW.workspace_id) THEN RAISE EXCEPTION 'Approval scope mismatch'; END IF;
IF NEW.kind='asset' AND (NEW.storage_path IS NULL OR NEW.storage_path NOT LIKE NEW.org_id::text||'/'||NEW.workspace_id::text||'/'||NEW.entity_id::text||'/%' OR NEW.storage_path ~ '(^|/)\.\.?(/|$)') THEN RAISE EXCEPTION 'Attachment scope mismatch'; END IF;
IF TG_OP='UPDATE' AND (NEW.entity_id IS DISTINCT FROM OLD.entity_id OR NEW.entity_type IS DISTINCT FROM OLD.entity_type OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.related_id IS DISTINCT FROM OLD.related_id OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.storage_path IS DISTINCT FROM OLD.storage_path) THEN RAISE EXCEPTION 'Parent identity is immutable'; END IF;
END IF;
RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.execution_activity_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n jsonb:=to_jsonb(NEW); BEGIN INSERT INTO public.activity_events(org_id,workspace_id,entity_type,entity_id,actor_id,action,metadata) VALUES(NEW.org_id,NEW.workspace_id,CASE WHEN TG_TABLE_NAME='execution_notes' THEN NEW.entity_type ELSE TG_TABLE_NAME END,CASE WHEN TG_TABLE_NAME='execution_notes' THEN (n->>'entity_id')::uuid ELSE NEW.id END,auth.uid(),lower(TG_OP),jsonb_build_object('title',n->>'title','status',n->>'status','kind',n->>'kind')); RETURN NEW; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['projects','tasks','campaigns','execution_notes'] LOOP EXECUTE format('CREATE POLICY execution_read ON public.%I FOR SELECT TO authenticated USING(public.has_workspace_role(workspace_id,''viewer''))',t); EXECUTE format('CREATE POLICY execution_create ON public.%I FOR INSERT TO authenticated WITH CHECK(public.has_workspace_role(workspace_id,''member'') AND created_by=auth.uid())',t); EXECUTE format('CREATE POLICY execution_update ON public.%I FOR UPDATE TO authenticated USING(public.has_workspace_role(workspace_id,''member'')) WITH CHECK(public.has_workspace_role(workspace_id,''member''))',t); EXECUTE format('CREATE TRIGGER execution_guard BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_execution()',t); EXECUTE format('CREATE TRIGGER execution_history AFTER INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.execution_activity_trigger()',t); END LOOP; END $$;
CREATE POLICY execution_note_delete ON public.execution_notes FOR DELETE TO authenticated USING(public.has_workspace_role(workspace_id,'member') AND (created_by=auth.uid() OR public.has_workspace_role(workspace_id,'admin')));
CREATE TRIGGER projects_touch BEFORE UPDATE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER tasks_touch BEFORE UPDATE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at(); CREATE TRIGGER campaigns_touch BEFORE UPDATE ON public.campaigns FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE UNIQUE INDEX execution_link_unique ON public.execution_notes(entity_id,kind,related_id) WHERE related_id IS NOT NULL; CREATE UNIQUE INDEX execution_member_unique ON public.execution_notes(entity_id,kind,user_id) WHERE user_id IS NOT NULL;
CREATE INDEX execution_tasks_scope_due ON public.tasks(workspace_id,due_date,status); CREATE INDEX execution_projects_scope ON public.projects(workspace_id,status); CREATE INDEX execution_campaigns_scope ON public.campaigns(workspace_id,status); CREATE INDEX execution_notes_parent ON public.execution_notes(workspace_id,entity_id); CREATE INDEX execution_events_scope ON public.activity_events(workspace_id,created_at DESC);
CREATE POLICY execution_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='execution-files' AND public.document_path_access(name,'viewer'));
CREATE POLICY execution_files_create ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='execution-files' AND public.document_path_access(name,'member'));
CREATE POLICY execution_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='execution-files' AND public.document_path_access(name,'member') AND owner_id=auth.uid()::text);
CREATE OR REPLACE FUNCTION public.convert_execution_plan(_workspace uuid,_source uuid,_kind text,_request uuid,_plan jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE oid uuid; existing jsonb; parent uuid; taskid uuid; ids jsonb:='[]'; item jsonb; resultj jsonb; titlev text; BEGIN
SELECT org_id INTO oid FROM public.workspaces WHERE id=_workspace FOR UPDATE; IF oid IS NULL OR NOT public.has_workspace_role(_workspace,'member') THEN RAISE EXCEPTION 'forbidden'; END IF;
IF _kind NOT IN ('project','tasks','campaign') OR _request IS NULL THEN RAISE EXCEPTION 'Invalid conversion'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.messages m JOIN public.conversations c ON c.id=m.conversation_id WHERE m.id=_source AND m.role='assistant' AND c.workspace_id=_workspace AND c.org_id=oid AND c.user_id=auth.uid()) THEN RAISE EXCEPTION 'Source recommendation unavailable'; END IF;
SELECT result INTO existing FROM public.execution_conversions WHERE workspace_id=_workspace AND (request_key=_request OR (source_message_id=_source AND kind=_kind)); IF existing IS NOT NULL THEN RETURN existing; END IF;
IF jsonb_typeof(_plan->'tasks') IS DISTINCT FROM 'array' OR jsonb_array_length(_plan->'tasks') NOT BETWEEN 1 AND 40 THEN RAISE EXCEPTION 'Plan needs 1 to 40 tasks'; END IF;
titlev:=trim(_plan->>'title');
IF _kind='project' THEN INSERT INTO public.projects(org_id,workspace_id,title,description,objective,source_message_id) VALUES(oid,_workspace,titlev,coalesce(_plan->>'description',''),coalesce(_plan->>'objective',''),_source) RETURNING id INTO parent;
ELSIF _kind='campaign' THEN INSERT INTO public.campaigns(org_id,workspace_id,title,description,objective,category,source_message_id) VALUES(oid,_workspace,titlev,coalesce(_plan->>'description',''),coalesce(_plan->>'objective',''),coalesce(_plan->>'category','marketing'),_source) RETURNING id INTO parent; END IF;
FOR item IN SELECT value FROM jsonb_array_elements(_plan->'tasks') LOOP
IF EXISTS(SELECT 1 FROM jsonb_array_elements(_plan->'tasks') t WHERE lower(trim(t->>'title'))=lower(trim(item->>'title')) GROUP BY lower(trim(t->>'title')) HAVING count(*)>1) THEN RAISE EXCEPTION 'Duplicate task titles'; END IF;
INSERT INTO public.tasks(org_id,workspace_id,title,description,priority,due_date,owner_id,project_id,campaign_id,source_message_id) VALUES(oid,_workspace,trim(item->>'title'),coalesce(item->>'description',''),coalesce(item->>'priority','medium'),nullif(item->>'due_date','')::date,nullif(item->>'owner_id','')::uuid,CASE WHEN _kind='project' THEN parent END,CASE WHEN _kind='campaign' THEN parent END,_source) RETURNING id INTO taskid; ids:=ids||jsonb_build_array(taskid); END LOOP;
resultj:=jsonb_build_object('kind',_kind,'parent_id',parent,'task_ids',ids); INSERT INTO public.execution_conversions(org_id,workspace_id,source_message_id,kind,request_key,result) VALUES(oid,_workspace,_source,_kind,_request,resultj); RETURN resultj;
END $$;
REVOKE ALL ON FUNCTION public.convert_execution_plan(uuid,uuid,text,uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.convert_execution_plan(uuid,uuid,text,uuid,jsonb) TO authenticated;
REVOKE ALL ON FUNCTION public.guard_execution(),public.execution_activity_trigger() FROM PUBLIC;
COMMENT ON TABLE public.execution_notes IS 'Typed parent-scoped records for project members/milestones, task assignees/dependencies/comments, campaign assets/approvals and attachments. Campaign tasks use tasks.campaign_id; project tasks use tasks.project_id.';